package com.droidbubble.app.island

import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.drawWithContent
import androidx.compose.ui.graphics.drawscope.translate
import androidx.compose.ui.graphics.vector.ImageVector
import com.droidbubble.app.icons.IslandGlyphs

/**
 * Every glyph the island draws, named by meaning (V7.1), from Material Symbols Rounded at weight
 * 500, grade -25, filled (V7.3, generated by tools/material-symbols.py into [IslandGlyphs]).
 * Island code never reaches for `Icons.*` or the glyph file itself (IslandIconsTest checks), so
 * the dynamic-icon engine (epic I) has one seam to replace glyphs at.
 *
 * The top level is optical size 24, for cards. [Compact] holds the same glyphs at optical size 20,
 * drawn heavier and more open for small sizes: the pill, the bubble and the alert pills use those.
 */
object IslandIcons {
    // ---- activities ----
    val Notification: ImageVector get() = IslandGlyphs.Notifications
    val Call: ImageVector get() = IslandGlyphs.Call
    val CallEnd: ImageVector get() = IslandGlyphs.CallEnd
    val Flashlight: ImageVector get() = IslandGlyphs.FlashlightOn
    val Download: ImageVector get() = IslandGlyphs.Download
    val MusicNote: ImageVector get() = IslandGlyphs.MusicNote
    val Mic: ImageVector get() = IslandGlyphs.Mic
    val Timer: ImageVector get() = IslandGlyphs.Timer
    val Alarm: ImageVector get() = IslandGlyphs.Alarm
    val Delivery: ImageVector get() = IslandGlyphs.LocalShipping
    val Sports: ImageVector get() = IslandGlyphs.SportsSoccer

    // ---- system alerts ----
    val Unlocked: ImageVector get() = IslandGlyphs.LockOpen
    val Bluetooth: ImageVector get() = IslandGlyphs.Bluetooth
    val Wifi: ImageVector get() = IslandGlyphs.Wifi
    val Charging: ImageVector get() = IslandGlyphs.Bolt
    val RingerOn: ImageVector get() = IslandGlyphs.Notifications
    val RingerSilent: ImageVector get() = IslandGlyphs.NotificationsOff
    val RingerVibrate: ImageVector get() = IslandGlyphs.Vibration
    val Done: ImageVector get() = IslandGlyphs.Check

    // ---- controls ----
    val Play: ImageVector get() = IslandGlyphs.PlayArrow
    val Pause: ImageVector get() = IslandGlyphs.Pause
    val SkipNext: ImageVector get() = IslandGlyphs.SkipNext
    val SkipPrevious: ImageVector get() = IslandGlyphs.SkipPrevious
    val Shuffle: ImageVector get() = IslandGlyphs.Shuffle
    val Repeat: ImageVector get() = IslandGlyphs.Repeat
    val RepeatOne: ImageVector get() = IslandGlyphs.RepeatOne
    /** Mirrors in right-to-left layouts, so the arrow points the way text flows. */
    val Send: ImageVector get() = IslandGlyphs.Send
    val Close: ImageVector get() = IslandGlyphs.Close

    /** The same glyphs at optical size 20, for the pill, the bubble and the alert pills. */
    object Compact {
        // ---- activities ----
        val Notification: ImageVector get() = IslandGlyphs.Small.Notifications
        val Call: ImageVector get() = IslandGlyphs.Small.Call
        val CallEnd: ImageVector get() = IslandGlyphs.Small.CallEnd
        val Flashlight: ImageVector get() = IslandGlyphs.Small.FlashlightOn
        val Download: ImageVector get() = IslandGlyphs.Small.Download
        val MusicNote: ImageVector get() = IslandGlyphs.Small.MusicNote
        val Mic: ImageVector get() = IslandGlyphs.Small.Mic
        val Timer: ImageVector get() = IslandGlyphs.Small.Timer
        val Alarm: ImageVector get() = IslandGlyphs.Small.Alarm
        val Delivery: ImageVector get() = IslandGlyphs.Small.LocalShipping
        val Sports: ImageVector get() = IslandGlyphs.Small.SportsSoccer

        // ---- system alerts ----
        val Unlocked: ImageVector get() = IslandGlyphs.Small.LockOpen
        val Bluetooth: ImageVector get() = IslandGlyphs.Small.Bluetooth
        val Wifi: ImageVector get() = IslandGlyphs.Small.Wifi
        val Charging: ImageVector get() = IslandGlyphs.Small.Bolt
        val RingerOn: ImageVector get() = IslandGlyphs.Small.Notifications
        val RingerSilent: ImageVector get() = IslandGlyphs.Small.NotificationsOff
        val RingerVibrate: ImageVector get() = IslandGlyphs.Small.Vibration
        val Done: ImageVector get() = IslandGlyphs.Small.Check

        // ---- controls ----
        val Play: ImageVector get() = IslandGlyphs.Small.PlayArrow
        val Pause: ImageVector get() = IslandGlyphs.Small.Pause
        val SkipNext: ImageVector get() = IslandGlyphs.Small.SkipNext
        val SkipPrevious: ImageVector get() = IslandGlyphs.Small.SkipPrevious
        val Shuffle: ImageVector get() = IslandGlyphs.Small.Shuffle
        val Repeat: ImageVector get() = IslandGlyphs.Small.Repeat
        val RepeatOne: ImageVector get() = IslandGlyphs.Small.RepeatOne
        /** Mirrors in right-to-left layouts, so the arrow points the way text flows. */
        val Send: ImageVector get() = IslandGlyphs.Small.Send
        val Close: ImageVector get() = IslandGlyphs.Small.Close
    }

    /**
     * How far to shift a glyph so its ink sits on the centre of its box (V7.2), as fractions of
     * the glyph size (+x right, +y down). Measured from each glyph's ink centroid (see
     * GlyphCentroidProbe); only glyphs whose box is visibly framed (a round button, a tile, the
     * bubble) are listed, the rest draw as designed.
     */
    private val opticalShift: Map<String, Pair<Float, Float>> = mapOf(
        "Symbols.PlayArrow" to (0.013f to 0f),
        "Symbols.SkipNext" to (0.027f to 0f),
        "Symbols.SkipPrevious" to (-0.027f to 0f),
        "Symbols.Download" to (0f to -0.104f),
        "Symbols.Notifications" to (0f to -0.015f),
        "Symbols.Mic" to (0f to 0.035f),
        "Symbols.PlayArrow.20" to (0.007f to 0f),
        "Symbols.SkipNext.20" to (0.018f to 0f),
        "Symbols.SkipPrevious.20" to (-0.018f to 0f),
        "Symbols.Download.20" to (0f to -0.074f),
        "Symbols.Notifications.20" to (0f to -0.016f),
        "Symbols.Mic.20" to (0f to 0.037f),
    )

    fun opticalShiftOf(icon: ImageVector): Pair<Float, Float>? = opticalShift[icon.name]
}

/**
 * Draws [icon] shifted so it looks centred in its box ([IslandIcons.opticalShiftOf]). A draw-phase
 * translate: no layout change, sub-pixel exact, and not mirrored in right-to-left layouts, because
 * the glyphs themselves aren't.
 */
fun Modifier.opticalCenter(icon: ImageVector): Modifier {
    val (fx, fy) = IslandIcons.opticalShiftOf(icon) ?: return this
    return drawWithContent { translate(size.width * fx, size.height * fy) { this@drawWithContent.drawContent() } }
}
